    fn class_id_from_mirror(&self, mirror: ObjectRef) -> Option<ClassId> {
        // JIT round 17 wave 8, lane nio3 (`CRATONVM_CLASS_ID_FROM_MIRROR_MEMO`,
        // opt-in): a per-thread memo keyed by the pause generation, loaded
        // BEFORE the locked lookup; see `cratonvm_native_builtins::mirror_id_memo`.
        //
        // JIT round 18 wave 10, lane buffers (`CRATONVM_CLASS_ID_FROM_MIRROR_TABLE`,
        // opt-in, decided per VM when the table was built): the same contract
        // on a per-VM, lock-free table shared by every thread; it takes
        // precedence over the per-thread memo.
        let table = &self.shared.classes.class_mirror_id_table;
        if table.is_enabled() {
            let generation = self
                .shared
                .mem
                .gc_barrier
                .gc_generation
                .load(std::sync::atomic::Ordering::Acquire);
            return table.lookup_or_fill(generation, mirror.as_ptr() as usize, || {
                super::class_id_from_mirror(self.shared, mirror)
            });
        }
        if !cratonvm_native_builtins::mirror_id_memo::enabled() {
            return super::class_id_from_mirror(self.shared, mirror);
        }
        let generation = self
            .shared
            .mem
            .gc_barrier
            .gc_generation
            .load(std::sync::atomic::Ordering::Acquire);
        cratonvm_native_builtins::mirror_id_memo::lookup_or_fill(
            self.shared.vm_identity,
            generation,
            mirror.as_ptr() as usize,
            || super::class_id_from_mirror(self.shared, mirror),
        )
    }

    fn note_class_mirror_id(&self, mirror: ObjectRef, class_id: ClassId, kind: &dyn Fn() -> u8) {
        // JIT round 20 wave 19, lane zAssign: the compiled
        // `Class.isAssignableFrom` / `isInstance` arms' mirror hints.
        crate::jit::helpers::class_mirror_id_hint_fill(self.shared, mirror, class_id, kind);
    }

