    /// the backend's per-collection line, for this VM only.
    fn set_verbose_gc(&self, on: bool) {
        self.shared
            .mem
            .verbose_gc
            .store(on, std::sync::atomic::Ordering::Relaxed);
        self.shared.mem.heap.set_gc_logging(on);
    }

