            cratonvm_jfr::builtin::emit_monitor_wait_event(
                &mut jfr,
                "java/lang/Object",
                "unknown",
                timeout_ns,
                was_interrupted,
                obj.as_ptr() as i64,
                self.thread.thread_id.0 as u64,
                now_ns.saturating_sub(wait_dur.as_nanos() as u64),
                wait_dur.as_nanos() as u64,
            );
