    #[test]
    fn cas_equal_ints() {
        assert!(values_equal_for_cas(&Value::Int(42), &Value::Int(42)));
    }

    #[test]
    fn cas_different_ints() {
        assert!(!values_equal_for_cas(&Value::Int(1), &Value::Int(2)));
    }

    #[test]
    fn cas_equal_longs() {
        assert!(values_equal_for_cas(&Value::Long(100), &Value::Long(100)));
    }

    #[test]
    fn cas_different_longs() {
        assert!(!values_equal_for_cas(&Value::Long(1), &Value::Long(2)));
    }

    #[test]
    fn cas_equal_floats() {
        assert!(values_equal_for_cas(&Value::Float(1.5), &Value::Float(1.5)));
    }

    #[test]
    fn cas_float_nan_bit_equal() {
        // CAS uses bit equality, so NaN == NaN
        assert!(values_equal_for_cas(
            &Value::Float(f32::NAN),
            &Value::Float(f32::NAN)
        ));
    }

    #[test]
    fn cas_float_pos_neg_zero_different_bits() {
        // +0.0 and -0.0 have different bits
        assert!(!values_equal_for_cas(
            &Value::Float(0.0),
            &Value::Float(-0.0)
        ));
    }

    #[test]
    fn cas_equal_doubles() {
        assert!(values_equal_for_cas(
            &Value::Double(2.5),
            &Value::Double(2.5)
        ));
    }

    #[test]
    fn cas_double_nan_bit_equal() {
        assert!(values_equal_for_cas(
            &Value::Double(f64::NAN),
            &Value::Double(f64::NAN)
        ));
    }

    // -----------------------------------------------------------------------
    // coerce_value_for_return — B4 (null/primitive coercion, no truncation)
    // -----------------------------------------------------------------------

    #[test]
    fn coerce_null_object_to_int_is_zero() {
        // Object(None) reaching an int slot becomes the zero default.
        assert_eq!(
            coerce_value_for_return(Value::Object(None), b'I'),
            Value::Int(0)
        );
        assert_eq!(
            coerce_value_for_return(Value::Object(None), b'Z'),
            Value::Int(0)
        );
    }

    #[test]
    fn coerce_null_object_to_long_is_zero() {
        assert_eq!(
            coerce_value_for_return(Value::Object(None), b'J'),
            Value::Long(0)
        );
    }

    /// Interpreter round i7 wave 143, lane L2: the `F`/`D` arms no longer pass
    /// a reference through to a primitive operand-stack slot.
    #[test]
    fn coerce_null_object_to_float_and_double_is_zero() {
        assert!(matches!(
            coerce_value_for_return(Value::Object(None), b'F'),
            Value::Float(v) if v == 0.0
        ));
        assert!(matches!(
            coerce_value_for_return(Value::Object(None), b'D'),
            Value::Double(v) if v == 0.0
        ));
        // The bit-reinterpretation arms are unchanged.
        assert!(matches!(
            coerce_value_for_return(Value::Int(1.5f32.to_bits() as i32), b'F'),
            Value::Float(v) if v == 1.5
        ));
    }

    #[test]
    fn coerce_long_to_int_truncates_value_not_pointer() {
        // Legitimate Long->I narrowing (a primitive smuggled as Long) is
        // unchanged by the B4 fix — only the Object(Some) pointer arm changed.
        assert_eq!(
            coerce_value_for_return(Value::Long(0x1_0000_0001), b'I'),
            Value::Int(1)
        );
    }

    #[test]
    fn coerce_int_to_long_widens() {
        assert_eq!(
            coerce_value_for_return(Value::Int(-1), b'J'),
            Value::Long(-1)
        );
    }

    #[test]
    fn object_serialization_hook_neutral_result_matches_objectstream_hooks() {
        assert_eq!(
            object_serialization_hook_neutral_result(
                "readObject",
                "(Ljava/io/ObjectInputStream;)V",
                &[]
            ),
            Some(None)
        );
        assert_eq!(
            object_serialization_hook_neutral_result(
                "writeReplace",
                "()Ljava/lang/Object;",
                &[Value::Object(None)]
            ),
            Some(Some(Value::Object(None)))
        );
        assert_eq!(
            object_serialization_hook_neutral_result("clone", "()Ljava/lang/Object;", &[]),
            None
        );
    }

    #[test]
    fn coerce_aligned_long_to_ref_does_not_fabricate_objectref() {
        // vm-vmexec-coerce: a non-zero, 8-aligned `Value::Long` (e.g. a hash /
        // size / length that happens to satisfy `p != 0 && p % 8 == 0`) reaching
        // an `L`/`[` return slot must NOT be reinterpreted as a heap `ObjectRef`
        // by this heap-unaware coercer — that fabricated pointer would later be
        // marked/moved by GC and crash. It now coerces to `null`; a real
        // jobject-as-jlong handle must go through
        // `coerce_value_for_return_validated`, which checks heap membership.
        //
        // `jlong_bits_as_aligned_object_ptr` only recognizes bits that have
        // actually crossed the `ObjectRef::from_raw`/`from_raw_nonnull`
        // provenance boundary (see `types/src/value.rs`) — a bare untouched
        // constant has no provenance entry and correctly returns `None`. So
        // register this address first, exactly like the analogous
        // `jlong_bits_as_aligned_object_ptr_matches_coerce_contract` test in
        // `types/src/value.rs` does, to exercise the "known, aligned, but
        // still not heap-validated" case this test is actually about.
        let aligned = 0x4000_0000u64; // != 0 and 8-aligned
        let _known = unsafe { ObjectRef::from_raw(aligned as *mut u8) };
        assert!(jlong_bits_as_aligned_object_ptr(aligned).is_some());
        assert_eq!(
            coerce_value_for_return(Value::Long(aligned as i64), b'L'),
            Value::Object(None)
        );
        assert_eq!(
            coerce_value_for_return(Value::Long(aligned as i64), b'['),
            Value::Object(None)
        );
        // A genuine object return is forwarded unchanged.
        assert_eq!(
            coerce_value_for_return(Value::Object(None), b'L'),
            Value::Object(None)
        );
    }

    // -----------------------------------------------------------------------
    // V2 — descriptor arity helper used to guard JNI native dispatch
    // -----------------------------------------------------------------------

    #[test]
    fn jni_arity_helper_matches_jvm_spec_param_count() {
        // long/double count as one parameter (matches the one-Value-per-param
        // shape of `call_args`), so the dispatch guard compares like-for-like.
        assert_eq!(crate::runtime::proxy::count_descriptor_params("()V"), 0);
        assert_eq!(crate::runtime::proxy::count_descriptor_params("(I)V"), 1);
        assert_eq!(
            crate::runtime::proxy::count_descriptor_params("(JD)V"),
            2,
            "long+double are one param each"
        );
        assert_eq!(
            crate::runtime::proxy::count_descriptor_params("(Ljava/lang/String;[IJ)Z"),
            3
        );
    }

    // -----------------------------------------------------------------------
    // JniContextGuard — TLS context is cleared on drop AND on unwind
    // -----------------------------------------------------------------------

    #[test]
    fn jni_context_guard_clears_on_normal_drop() {
        // Run on a dedicated OS thread so the JNI TLS we touch here cannot
        // leak into (or be observed by) other tests sharing the main thread.
        std::thread::spawn(|| {
            let shared = test_shared();
            // `replace_jni_context` (called by the guard) clones an Arc via
            // `SharedVm::get_arc()`, which requires the weak self-reference that
            // only `Vm::new()` installs. `test_shared()` skips `Vm::new`, so set
            // it here exactly as `Vm::new` does before exercising the guard.
            *shared.self_arc.write() = Some(std::sync::Arc::downgrade(&shared));
            // No live JvmThread is needed: the guard only stores the raw
            // pointer in TLS; we never deref it. A dangling-but-unused pointer
            // is fine for exercising the install/clear lifecycle.
            {
                let _g = unsafe { JniContextGuard::install(&shared, std::ptr::null_mut()) };
                // Context is installed here; nothing to assert without a public
                // TLS predicate — the value of the test is the unwind case below.
            }
            // After the guard drops, the TLS context is clear. `clear_jni_*`
            // are idempotent, so re-clearing is a harmless no-op that documents
            // the post-condition.
            crate::native::jni::clear_jni_context();
            crate::native::jni::clear_jni_thread();
        })
        .join()
        .expect("guard install/drop thread should not panic");
    }

    #[test]
    fn jni_context_guard_clears_on_unwind() {
        // The whole point of the RAII guard (vs. the old manual clear pair) is
        // that an unwind through the native bridge still clears the TLS
        // pointers. Construct the guard inside a panicking `catch_unwind` and
        // confirm: (a) the closure unwound (Err), and (b) the thread is left in
        // a usable state where a fresh guard can be installed and dropped again
        // — which is only true if the first guard's `Drop` ran during unwind.
        std::thread::spawn(|| {
            let shared = test_shared();
            // See `jni_context_guard_clears_on_normal_drop`: install the weak
            // self-reference `get_arc()` needs, which `test_shared()` omits.
            *shared.self_arc.write() = Some(std::sync::Arc::downgrade(&shared));
            let unwound = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                let _g = unsafe { JniContextGuard::install(&shared, std::ptr::null_mut()) };
                panic!("simulated native-bridge unwind");
            }));
            assert!(unwound.is_err(), "closure should have unwound");

            // If the guard's Drop did NOT run, a stale context would remain.
            // Re-installing and dropping a second guard must still succeed.
            {
                let _g2 = unsafe { JniContextGuard::install(&shared, std::ptr::null_mut()) };
            }
            crate::native::jni::clear_jni_context();
            crate::native::jni::clear_jni_thread();
        })
        .join()
        .expect("post-unwind thread should not panic");
    }

    // -----------------------------------------------------------------------
    // native_range_is_in_bounds — overflow guard for raw native copies
    // -----------------------------------------------------------------------

    #[test]
    fn native_range_zero_len_is_in_bounds() {
        // A zero-length copy is a no-op and always in bounds, even at the very
        // top of the address space.
        assert!(native_range_is_in_bounds(0, 0));
        assert!(native_range_is_in_bounds(u64::MAX, 0));
    }

    #[test]
    fn native_range_ordinary_is_in_bounds() {
        assert!(native_range_is_in_bounds(0x1000, 64));
    }

    #[test]
    fn native_range_exact_end_is_in_bounds() {
        // base + len == u64::MAX + 1 is the first wrapping value; one below the
        // end must still be accepted.
        assert!(native_range_is_in_bounds(u64::MAX - 8, 8));
    }

    #[test]
    fn native_range_wrapping_is_rejected() {
        // A forged length that pushes the end past u64::MAX wraps — reject it.
        assert!(!native_range_is_in_bounds(u64::MAX, 1));
        assert!(!native_range_is_in_bounds(u64::MAX - 4, 16));
    }

    // -----------------------------------------------------------------------
    // claim_raw_join_handle — exactly-once consumption / double-free guard
    // -----------------------------------------------------------------------

    #[test]
    fn claim_raw_join_handle_first_claim_succeeds_repeat_fails() {
        // The set backing `claim_raw_join_handle` is process-global, so use
        // distinctive sentinel values unlikely to collide with any real
        // allocation or another test. These are NEVER reconstructed via
        // Box::from_raw — only the dedup predicate is exercised.
        let p1 = 0xDEAD_BEEF_0000_1001usize;
        let p2 = 0xDEAD_BEEF_0000_1002usize;

        // First claim of a fresh pointer succeeds.
        assert!(claim_raw_join_handle(p1));
        // A second claim of the same pointer is rejected (would be a double
        // consume → double-free at the call site).
        assert!(!claim_raw_join_handle(p1));
        // A different pointer is independent and still claimable.
        assert!(claim_raw_join_handle(p2));
        assert!(!claim_raw_join_handle(p2));
    }

