    /// gcg g2/w, `CRATONVM_STRING_INTERN_RETURNS_RECEIVER`: off (`=0`; on by default),
    /// `intern_string_receiver` declines and `String.intern()` keeps building a
    /// new pooled String; on, a miss pools and answers the receiver itself
    /// (`s.intern() == s`, as on HotSpot) and a hit answers the pooled String.
    #[test]
    fn gcg_w2_intern_string_receiver_follows_the_switch() {
        let shared = test_shared();
        let mut thread = JvmThread::new(ThreadId(0), "test");
        let mut ctx = NativeContextImpl {
            shared: &shared,
            thread: &mut thread,
        };
        let fresh = ctx.create_string_uninterned("gcg-w2-receiver");
        shared.mem.string_table.set_intern_returns_receiver(false);
        assert_eq!(ctx.intern_string_receiver(fresh, "gcg-w2-receiver"), None);
        assert!(!shared
            .mem
            .string_pool
            .read()
            .contains_key("gcg-w2-receiver"));

        shared.mem.string_table.set_intern_returns_receiver(true);
        assert_eq!(
            ctx.intern_string_receiver(fresh, "gcg-w2-receiver"),
            Some(fresh),
            "a miss pools the receiver"
        );
        let other = ctx.create_string_uninterned("gcg-w2-receiver");
        assert_eq!(
            ctx.intern_string_receiver(other, "gcg-w2-receiver"),
            Some(fresh),
            "a hit answers the pooled String"
        );
        assert_eq!(
            ctx.intern_string("gcg-w2-receiver"),
            fresh,
            "and so does intern_string"
        );
    }

