/// Interpreter round i4 wave 95, lane L7 (`CRATONVM_INTERP_CLASS_MEMO_NARROW_EPOCH`,
/// `class_id_memo_epoch`): with the switch on, a definition of an unrelated
/// class leaves the class-id memos' stamp alone, and an in-place provenance
/// write (a stub promoted to its real bytes) still retires a transient
/// descriptor answer. Each test sets the switch on its own VM explicitly.
#[cfg(test)]
mod i95_l7_class_memo_narrow_epoch_tests {
    use super::*;
    use crate::config::VmConfig;
    use std::sync::Arc;

    fn narrow_shared() -> Arc<SharedVm> {
        let mut config = VmConfig::default();
        config.class_memo_narrow_epoch = true;
        Arc::new(SharedVm::new(config))
    }

    /// A real class with one instance field of each descriptor, no
    /// superclass, registered under `name` (the shape of the module tests'
    /// `add_real_class_with_field_descriptors`).
    fn add_class(shared: &SharedVm, name: &str, descriptors: &[&str]) -> ClassId {
        use cratonvm_classloading::{Class, ClassLoaderId, ClassState};
        use cratonvm_reader::class_access_flags::{ClassAccessFlags, FieldAccessFlags};
        use cratonvm_reader::class_file_version::ClassFileVersion;
        use cratonvm_reader::constant_pool::{ConstantPool, ConstantPoolEntry};
        use cratonvm_reader::field::ClassFileField;

        let fields: Vec<ClassFileField> = descriptors
            .iter()
            .enumerate()
            .map(|(i, d)| ClassFileField {
                access_flags: FieldAccessFlags::PRIVATE,
                name: Arc::from(format!("f{i}")),
                descriptor: Arc::from(*d),
                attributes: Vec::new(),
            })
            .collect();
        let num_fields = fields.len();
        let mut cm = shared.classes.class_manager_write();
        let id = cm.class_store.next_id();
        cm.class_store.add(Class {
            id,
            loader_id: ClassLoaderId::Application,
            name: Arc::from(name),
            source_file: None,
            version: ClassFileVersion::JAVA_8,
            state: ClassState::Initialized,
            initializing_thread: None,
            constant_pool: ConstantPool::new(vec![ConstantPoolEntry::Tombstone]),
            access_flags: ClassAccessFlags::PUBLIC | ClassAccessFlags::SUPER,
            superclass: None,
            interfaces: vec![],
            fields,
            methods: vec![],
            first_field_index: 0,
            num_total_fields: num_fields,
            bootstrap_methods: vec![],
            annotations: Vec::new(),
            nest_host: None,
            nest_members: Vec::new(),
            record_components: Vec::new(),
            permitted_subclasses: Vec::new(),
            inner_classes: Vec::new(),
            enclosing_method: None,
            hidden: false,
            module_name: None,
            origin: cratonvm_classloading::ClassOrigin::default(),
            has_finalizer: false,
            signature: None,
            code_source: None,
            array_info: None,
            init_state: std::sync::Arc::new(std::sync::atomic::AtomicU8::new(0)),
            record_object_methods: std::sync::atomic::AtomicU8::new(0),
        });
        cm.register_class_name(ClassLoaderId::Application, name, id);
        id
    }

    /// The narrow stamp does not move on a definition of an unrelated class
    /// (`class_origin_epoch` does). Both counters are process-shared with the
    /// tests running beside this one (the edge epoch per store slot, the
    /// in-place epoch in every slot), so a window spoiled by another test's
    /// write is retried; if the definition itself moved the stamp, every
    /// window would be dirty and this would fail.
    #[test]
    fn an_unrelated_definition_leaves_the_narrow_stamp() {
        let shared = narrow_shared();
        add_class(&shared, "i95l7/Base", &["I"]);
        const ATTEMPTS: usize = 64;
        let mut quiet = false;
        for i in 0..ATTEMPTS {
            let before = class_id_memo_epoch(&shared);
            let wide_before = cratonvm_classloading::class_origin_epoch();
            add_class(&shared, &format!("i95l7/Noise{i}"), &["J"]);
            assert!(
                cratonvm_classloading::class_origin_epoch() > wide_before,
                "a definition moves the wide stamp, or this test proves nothing"
            );
            if class_id_memo_epoch(&shared) == before {
                quiet = true;
                break;
            }
        }
        assert!(quiet, "no quiet window in {ATTEMPTS} definitions");
    }

    /// A transient answer (the receiver is a stub) memoised under the narrow
    /// stamp is retired by the stub's promotion (`set_origin`, which moves
    /// `class_origin_in_place_epoch`).
    #[test]
    fn a_promotion_retires_a_transient_answer_under_the_narrow_stamp() {
        let shared = narrow_shared();
        let cid = add_class(&shared, "i95l7/StubPromote", &["J"]);
        {
            let mut cm = shared.classes.class_manager_write();
            let cls = cm.class_store.get_mut(cid).expect("class present");
            cls.set_origin(cratonvm_classloading::ClassOrigin::compatibility_stub("i95l7"));
        }
        assert_eq!(resolve_field_descriptor_byte_cached(&shared, cid, 0), None);
        {
            let mut cm = shared.classes.class_manager_write();
            let cls = cm.class_store.get_mut(cid).expect("class present");
            cls.set_origin(cratonvm_classloading::ClassOrigin::default());
        }
        assert_eq!(
            resolve_field_descriptor_byte_cached(&shared, cid, 0),
            Some(b'J'),
            "the promoted class's real descriptor, not the stub's memoised miss"
        );
    }

    /// A positive by-name answer survives definitions under the narrow stamp
    /// and answers what the uncached walk answers.
    #[test]
    fn a_by_name_answer_is_the_walks_answer() {
        let shared = narrow_shared();
        let cid = add_class(&shared, "i95l7/ByName", &["I", "J"]);
        assert_eq!(resolve_field_slot_by_name_cached(&shared, cid, "f1"), Some(1));
        add_class(&shared, "i95l7/ByNameNoise", &["I"]);
        assert_eq!(resolve_field_slot_by_name_cached(&shared, cid, "f1"), Some(1));
        assert_eq!(resolve_field_slot_by_name_cached(&shared, cid, "f9"), None);
    }
}


#[cfg(test)]
mod infallible_thread_mirror_retirement_tests {
    use super::*;
    #[test]
    fn a_name_refusal_withdraws_the_provisional_mirror_and_can_retry() {
        let mut heaps = vec![
            crate::config::GcAlgorithm::Generational,
            crate::config::GcAlgorithm::G1,
        ];
        #[cfg(feature = "zgc")]
        heaps.push(crate::config::GcAlgorithm::Zgc);
        for heap in heaps {
            let mut vm = crate::vm::Vm::new(crate::config::VmConfig {
                gc_algorithm: heap,
                max_heap_size: 16 << 20,
                initial_heap_size: 16 << 20,
                ..crate::config::VmConfig::default()
            });
            let tid = vm.main_thread.thread_id;
            assert!(vm.main_thread.java_thread_obj.is_none());
            vm.main_thread.name = "x".repeat(32 << 20);
            let refused = {
                let mut ctx = NativeContextImpl {
                    shared: &vm.shared,
                    thread: &mut vm.main_thread,
                };
                ctx.build_current_thread_object()
            };
            assert!(refused.is_err());
            assert!(vm.main_thread.java_thread_obj.is_none());
            assert!(
                vm.shared
                    .threads
                    .thread_registry
                    .java_thread_obj(tid)
                    .is_none()
            );
            vm.main_thread.name = "recovered".into();
            let mirror = {
                let mut ctx = NativeContextImpl {
                    shared: &vm.shared,
                    thread: &mut vm.main_thread,
                };
                ctx.build_current_thread_object()
                    .expect("retry after a private failed construction")
            };
            assert_eq!(vm.main_thread.java_thread_obj, Some(mirror));
            assert_eq!(
                vm.shared.threads.thread_registry.java_thread_obj(tid),
                Some(mirror)
            );
        }
    }
}

/// gci i47w lane pr47 (holder page item 2): a blocking park deposits through
/// the lazy blocking-region deposit on G1, so the deferred-chain demotion
/// covers parked carriers.
#[cfg(test)]
mod gci_i47w_pr47_park_lazy_chain_tests {
    use super::park_deposit_defers_jit_chain;

    const SRC: &str = include_str!("vm_exec.rs");

    fn body(head: &str) -> &'static str {
        let start = SRC.find(head).unwrap_or_else(|| panic!("`{head}` missing"));
        let len = SRC[start..]
            .find("\n    \u{7d}\n")
            .unwrap_or_else(|| panic!("end of `{head}`"));
        &SRC[start..start + len]
    }

    fn at(hay: &str, needle: &str) -> usize {
        hay.find(needle)
            .unwrap_or_else(|| panic!("`{needle}` missing"))
    }

    /// The rule: G1 and the demotion switch, nothing else.
    #[test]
    fn gci_i47w_pr47_park_defers_its_chain_only_on_g1_with_the_demotion() {
        assert!(park_deposit_defers_jit_chain(true, true));
        assert!(!park_deposit_defers_jit_chain(true, false));
        assert!(!park_deposit_defers_jit_chain(false, true));
        assert!(!park_deposit_defers_jit_chain(false, false));
    }

    /// The park's window has the blocking region's shape around the lazy
    /// deposit: rule, deposit (both memo arms), key, blocked guard, wake.
    #[test]
    fn gci_i47w_pr47_park_takes_the_blocking_region_deposit_in_both_memo_arms() {
        let park = body("    fn park_with_state_inner(");
        let rule = at(park, "let lazy_chain = park_deposit_defers_jit_chain(");
        let lazy = at(park, "self.deposit_root_snapshot_for_blocking_region();");
        let key = at(park, "self.record_blocking_leave_key(leave_terms);");
        let guard = at(park, ".gc_barrier.enter_blocked();");
        let wake = at(park, "self.check_post_block_gc_quiet_refs(&mut []);");
        assert!(rule < lazy && lazy < key && key < guard && guard < wake);
        assert_eq!(
            park.matches("self.deposit_root_snapshot_for_blocking_region();")
                .count(),
            2,
            "the lazy deposit in the memo arm and in the plain arm"
        );
        assert_eq!(
            park.matches("self.deposit_root_snapshot();").count(),
            2,
            "the eager deposit kept for the switch off / a non-G1 heap"
        );
        assert!(park.contains("self.shared.mem.heap.is_g1(),"));
        assert!(park.contains(".park_defers_jit_chain(),"));
    }

    /// The lazy deposit is the eager one plus the deferral: the same cache
    /// clears, the same flag-raising inner deposit.
    #[test]
    fn gci_i47w_pr47_the_blocking_region_deposit_is_the_park_deposit_plus_the_deferral() {
        let eager = body("    pub(crate) fn deposit_root_snapshot(&mut self)");
        let lazy = body("    fn deposit_root_snapshot_for_blocking_region(&mut self)");
        for clear in [
            "self.thread.jit_hashmap_string_node_cache.clear();",
            "self.thread.string_case_cache.clear();",
        ] {
            assert!(eager.contains(clear) && lazy.contains(clear), "{clear}");
        }
        assert!(eager.contains("self.deposit_root_snapshot_inner(true);"));
        assert!(lazy.contains("self.deposit_root_snapshot_inner_with(true, lazy, false);"));
        assert!(lazy.contains("lazy_blocked_jit_deposit_enabled()"));
        assert!(lazy.contains("!= 4"), "a terminating thread keeps the eager walk");
        assert!(lazy.contains(".foreign_native"), "foreign code keeps the eager walk");
    }

    /// The registry's answer follows the demotion switch (default ON, `=0`
    /// kills), read once at construction.
    #[test]
    fn gci_i47w_pr47_registry_reads_the_demotion_switch() {
        use crate::threading::thread_registry::ThreadRegistry;
        let on = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_XT_HELPER_WINDOW_DEFERRED_CHAIN_NATIVE", None)],
            || ThreadRegistry::new().park_defers_jit_chain(),
        );
        let off = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_XT_HELPER_WINDOW_DEFERRED_CHAIN_NATIVE", Some("0"))],
            || ThreadRegistry::new().park_defers_jit_chain(),
        );
        assert!(on, "default ON");
        assert!(!off, "`=0` restores the eager park deposit");
    }
}

#[cfg(test)]
mod gci_i47w_jw1_windows_park_at_once_tests {
    //! gci i47w judge jw1 (item A of
    //! `gci-i23pk-park-permit-residuals-windows-and-stand-ins-FIXED-20261017`): on
    //! Windows an elapsed or negative deadline returns before the interrupt
    //! test and before the permit is taken, as HotSpot 25's os_windows.cpp
    //! `Parker::park` does; the Linux order (permit first) is unchanged.
    const SRC: &str = include_str!("vm_exec.rs");

    fn park_body() -> &'static str {
        let head = "    fn park_with_state_inner(";
        let start = SRC.find(head).expect("park_with_state_until");
        let len = SRC[start..]
            .find("\n    \u{7d}\n")
            .expect("end of park_with_state_until");
        &SRC[start..start + len]
    }

    #[test]
    fn gci_i47w_jw1_windows_at_once_park_keeps_the_permit_before_the_interrupt_test() {
        let park = park_body();
        let win = park
            .find("&& reported_timeout == Some(std::time::Duration::ZERO)")
            .expect("the Windows at-once return");
        let gate = park[..win]
            .rfind("#[cfg(windows)]")
            .expect("cfg(windows) gate");
        let interrupted = park
            .find("// JDK spec: if interrupted, park returns immediately")
            .expect("interrupt test");
        let permit = park.find("let had_permit = ").expect("permit take");
        assert!(gate < win && win < interrupted && interrupted < permit);
        let arm = &park[win..interrupted];
        assert!(arm.contains("!vm_scheduled_virtual(self.thread)"));
        assert!(arm.contains("self.commit_thread_park_event(span);"));
        assert!(arm.contains("return;"));
        assert!(!arm.contains("take_permit"), "the permit stays");
    }
}

#[cfg(test)]
mod gci_i47w_oz47_thread_start_class_load_attribution_tests {
    //! gci i47w lane oz47: a `Thread.start()` worker binds its class-load
    //! attribution (`cratonvm_classloading::set_current_thread_id`) to its own
    //! id before any Java runs and before its `ThreadStart`, so a C agent's
    //! `ClassLoad` for a class it defines is posted on its own `JvmThread`, not
    //! on thread 0's (`main`'s).

    /// Source pin: in the platform thread body the binding follows the OS-tid
    /// publication and precedes the C `ThreadStart` post.
    #[test]
    fn gci_i47w_oz47_started_thread_binds_its_class_load_thread_id() {
        let src = include_str!("vm_exec.rs").replace("\r\n", "\n");
        let os_tid = src
            .find("shared_arc.threads.thread_registry.set_os_tid_current(tid);")
            .expect("the OS-tid publication");
        let rest = &src[os_tid..];
        let bind = rest
            .find("cratonvm_classloading::set_current_thread_id(\n                shared_arc.classes.class_layout_domain,\n                tid.0,\n            );")
            .expect("the class-load attribution binding");
        let start = rest
            .find(concat!(
                "crate::jvmti::native_env::post_thread_event",
                "(&shared_arc, tid.0 as u64, true)"
            ))
            .expect("the C ThreadStart post");
        assert!(bind < start, "bound before ThreadStart and before run()");
        let ready = rest.find("mark_stw_ready(tid)").expect("the ready mark");
        assert!(bind < ready, "bound before the thread runs anything");
    }
}

/// JIT round 22 wave 4b, lane sync (`CRATONVM_HW_FLOAT_CAS`): the `float` /
/// `double` hardware-CAS kinds address the right cell, and are never published
/// to the compiled `Unsafe` read-modify-write prefixes.
#[cfg(test)]
mod r22_sync_hw_float_cas_tests {
    use super::HwAtomicKind;

    #[test]
    fn float_and_double_cells_are_never_published_to_the_unsafe_rmw_prefixes() {
        assert!(HwAtomicKind::Int.publishes_unsafe_rmw_cell());
        assert!(HwAtomicKind::Long.publishes_unsafe_rmw_cell());
        assert!(HwAtomicKind::Reference.publishes_unsafe_rmw_cell());
        assert!(!HwAtomicKind::Float.publishes_unsafe_rmw_cell());
        assert!(!HwAtomicKind::Double.publishes_unsafe_rmw_cell());
    }

    #[test]
    fn float_and_double_kinds_match_their_cells() {
        assert!(HwAtomicKind::Float.matches_descriptor(b'F'));
        assert!(!HwAtomicKind::Float.matches_descriptor(b'I'));
        assert!(HwAtomicKind::Double.matches_descriptor(b'D'));
        assert!(!HwAtomicKind::Double.matches_descriptor(b'J'));
        // `Value` tags (`field_cell_layout_matches_value_enum`): Float 2, Double 3.
        assert_eq!(HwAtomicKind::Float.legacy_tag(), 2);
        assert_eq!(HwAtomicKind::Double.legacy_tag(), 3);
        assert_eq!(HwAtomicKind::Float.width(), 4);
        assert_eq!(HwAtomicKind::Double.width(), 8);
        assert_eq!(
            HwAtomicKind::Float.payload_offset(),
            cratonvm_types::FIELD_CELL_PAYLOAD32_OFFSET
        );
        assert_eq!(
            HwAtomicKind::Double.payload_offset(),
            cratonvm_types::FIELD_CELL_PAYLOAD64_OFFSET
        );
    }

    /// The publish filter sits on the one publication site, and asks the kind.
    #[test]
    fn the_publication_site_filters_by_kind() {
        let src = include_str!("vm_exec.rs");
        let start = src.find("fn hw_atomic_addr_checked(").expect("hw_atomic_addr_checked moved");
        let body = &src[start..];
        let body = &body[..body.find("\n}\n").expect("function end")];
        let filter = body
            .find("publish.filter(|_| kind.publishes_unsafe_rmw_cell())")
            .expect("the kind filter on the publication");
        let first_publish = body
            .find("note_compact_ref_field(")
            .expect("the reference publication");
        assert!(filter < first_publish, "the filter must precede every publication");
        assert_eq!(body.matches("note_compact_field(").count(), 1);
    }

    /// Wave 4c: the sub-word lookup has no path into the `Unsafe` RMW cell
    /// tables, and the legacy narrowing is `putfield`'s.
    #[test]
    fn sub_word_cells_are_never_published_and_narrow_like_putfield() {
        let src = include_str!("vm_exec.rs");
        let start = src.find("fn hw_subword_cell(").expect("hw_subword_cell moved");
        let body = &src[start..];
        let body = &body[..body.find("\n}\n").expect("function end")];
        for publisher in ["note_compact_field(", "note_compact_ref_field(", "unsafe_inline", "hw_atomic_addr"] {
            assert!(!body.contains(publisher), "the sub-word lookup must not reach `{publisher}`");
        }
        // JIT round 21, lane atomics (UNSAFE21-2): the hardware sub-word CAS
        // publishes into the sub-word half only.
        let start = src
            .find("fn hw_cas_subword(")
            .expect("hw_cas_subword moved");
        let cas = &src[start..];
        let cas = &cas[..cas.find("\n}\n").expect("function end")];
        assert_eq!(cas.matches("note_compact_subword_field(").count(), 1);
        for publisher in [
            "note_compact_field(",
            "note_compact_ref_field(",
            "hw_atomic_addr",
        ] {
            assert!(
                !cas.contains(publisher),
                "the sub-word CAS must not reach `{publisher}`"
            );
        }
        use super::narrow_subword;
        assert_eq!(narrow_subword(b'B', 0x1FF), -1);
        assert_eq!(narrow_subword(b'B', 0x7F), 0x7F);
        assert_eq!(narrow_subword(b'S', 0x1_8000), -32768);
        assert_eq!(narrow_subword(b'C', -1), 0xFFFF);
        // Wave 5c: a boolean cell's CAS compares and stores the raw byte.
        assert_eq!(narrow_subword(b'Z', 3), 3);
        assert_eq!(narrow_subword(b'Z', 0x102), 2);
    }

    /// Wave 5b: a static cell's tag / payload encoding round-trips every kind
    /// the hardware static RMW serves, bit-exactly for floats, and refuses the
    /// rest (`ReturnAddress`, `Uninitialized`).
    #[test]
    fn static_cell_bits_round_trip() {
        use super::{static_cell_bits, static_cell_value};
        use cratonvm_types::Value;
        let nan = f64::from_bits(0x7ff8_0000_0000_0001);
        for v in [
            Value::Int(-7),
            Value::Long(i64::MIN),
            Value::Float(-0.0),
            Value::Double(nan),
            Value::Object(None),
        ] {
            let (tag, bits) = static_cell_bits(v).expect("served kind");
            let back = static_cell_value(tag, bits).expect("decodes");
            assert_eq!(static_cell_bits(back), Some((tag, bits)), "{v:?}");
        }
        assert_eq!(static_cell_bits(Value::Uninitialized), None);
        assert_eq!(static_cell_bits(Value::ReturnAddress(3)), None);
        assert_eq!(static_cell_value(6, 0), None);
    }
}

#[cfg(test)]
mod zt23zb8_refers_to_no_keepalive_tests {
    //! zt t23/zb8: `refersTo` reads the referent without keeping it alive
    //! (`NativeHeapAccess::get_field_no_keepalive`, ZGC's `Weak` load while
    //! the read barrier is armed). The GC half (the weak read never marks,
    //! the strong one does) is st1's `zt23st1_get_field_weak_never_marks_under_the_flip`;
    //! these pin the wiring.

    fn body_of<'a>(src: &'a str, head: &str, end: &str) -> &'a str {
        let start = src.find(head).expect("the function");
        let len = src[start..].find(end).expect("its end");
        &src[start..start + len]
    }

    /// The override: unarmed (or `=0`) it is exactly `get_field`; armed, the
    /// forwarded receiver's slot goes through `get_field_weak`. The armed test
    /// comes first, so a default run never asks the flag.
    #[test]
    fn zt23zb8_the_override_reads_weak_only_while_the_barrier_is_armed() {
        let src = include_str!("vm_exec.rs").replace("\r\n", "\n");
        let body = body_of(
            &src,
            concat!("    fn get_field_no_", "keepalive(&self"),
            "\n    \u{7d}\n",
        );
        let armed = body
            .find("zgc_load_barrier_armed()")
            .expect("the armed gate");
        let flag = body
            .find("env_cache::zgc_refers_to_no_keepalive()")
            .expect("the kill");
        let strong = body
            .find("return self.get_field(obj, index);")
            .expect("fallback");
        let weak = body
            .find(".get_field_weak(obj, index)")
            .expect("the weak read");
        assert!(armed < flag && flag < strong && strong < weak);
        assert!(body.contains("load_and_forward_checked(obj)"));
        assert!(!body.contains("referent_keep_alive"));
        assert!(!body.contains("satb_barrier"));
    }

    /// Every `refersTo0` reader of the referent: the two natives, the JIT
    /// direct helper and the leaf arm.
    #[test]
    fn zt23zb8_every_refers_to_reader_takes_the_no_keepalive_read() {
        let helpers = crate::jit::helpers::HELPERS_SRC.replace("\r\n", "\n");
        let direct = body_of(
            &helpers,
            concat!("unsafe fn jit_refers_to0_", "body("),
            "\n\u{7d}\n",
        );
        assert!(direct.contains("ctx.get_field_no_keepalive(this, 0)"));
        assert!(!direct.contains("ctx.get_field(this, 0)"));
        let leaf = body_of(
            &helpers,
            concat!("LeafNativeKind::Reference", "RefersTo => \u{7b}"),
            "LeafNativeKind::ClassIsInstance => \u{7b}",
        );
        assert!(leaf.contains("ctx.get_field_no_keepalive("));
        assert!(!leaf.contains("ctx.get_field("));

        let builtins = include_str!("../../../native-builtins/src/lib.rs").replace("\r\n", "\n");
        let native = body_of(
            &builtins,
            concat!("fn native_reference_refers_", "to(ctx"),
            "\n\u{7d}\n",
        );
        assert!(native.contains("ctx.get_field_no_keepalive(this, 0)"));
        assert!(!native.contains("ctx.get_field(this"));
        let reference =
            include_str!("../../../native-builtins/src/reference.rs").replace("\r\n", "\n");
        let native = body_of(
            &reference,
            concat!("fn native_ref_refers_", "to(ctx"),
            "\n\u{7d}\n",
        );
        assert!(native.contains("ctx.get_field_no_keepalive(this, REF_FIELD_REFERENT)"));
        assert!(!native.contains("ctx.get_field(this"));
    }
}

#[cfg(test)]
mod r25_w6f_parked_frame_sample_tests {
    fn body<'a>(src: &'a str, head: &str) -> &'a str {
        let start = src.find(head).expect(head);
        let rest = &src[start..];
        &rest[..rest.find("\n\u{7d}\n").expect("its end")]
    }

    /// r25 W6-F fix 6 (source pin): another thread's `ThreadInfo` is read
    /// at ONE instant -- the held read runs INSIDE the frame-trace pause --
    /// and that read takes the state, the trace with its block state, the
    /// attribution and the lock book from the registry alone.
    #[test]
    fn r25_w6f_a_thread_info_is_read_inside_one_pause() {
        let src = include_str!("vm_exec.rs").replace("\r\n", "\n");
        let start = src
            .find(concat!("    fn jmx_thread_", "snapshot(\n"))
            .expect("the snapshot");
        let rest = &src[start..];
        let snapshot = &rest[..rest.find("\n    }\n").expect("its end")];
        let pause = snapshot
            .find(concat!("stw_publish_frame_traces_", "with("))
            .expect("the pause");
        let read = snapshot
            .find(concat!("|| HeldThreadRead::", "read("))
            .expect("the held read");
        assert!(pause < read);
        let held = body(&src, "\nimpl HeldThreadRead {");
        for read in [
            "HeldTrace::read(registry, tid)",
            "registry.jmx_frame_monitors(tid, trace.trace.len())",
            "registry_run_state_for_block(registry, tid, thread_obj, block)",
            "registry.jmx_lock_snapshot(tid)",
        ] {
            assert!(held.contains(read), "{read}");
        }
        assert!(!held.contains(concat!("class_", "manager")));
        // W6-F fix 7: the book keeps only the monitors the thread holds.
        assert!(held.contains("drop_monitors_not_held(&shared.threads.monitors, tid, &mut book.2)"));
        let trace = body(&src, "\nimpl HeldTrace {");
        assert!(trace.contains("registry.frame_trace_of(tid)"));
        assert!(trace.contains("ParkedSample::read(registry, tid)"));
    }

    /// r25 W6-F (source pin): the parked leaf screen reads no block state of
    /// its own, and every published-trace reader hands it the one read with
    /// the trace.
    #[test]
    fn r25_w6f_the_screen_takes_the_state_read_with_the_trace() {
        let src = include_str!("vm_exec.rs").replace("\r\n", "\n");
        for head in [
            "\nfn append_parked_standin_entries(",
            "\npub(crate) fn parked_standin_frames_for_thread(",
        ] {
            let screen = body(&src, head);
            assert!(!screen.contains(concat!("java_block_", "state(")), "{head}");
        }
        let finish = body(&src, "\nfn finish_published_trace(");
        assert!(finish.contains("let HeldTrace { mut trace, parked } = held;"));
        assert!(finish.contains("append_parked_standin_entries(ctx.shared, &cm, parked,"));
        let served = body(&src, "\nfn thread_stack_trace_served(");
        assert!(served.contains("HeldTrace::read(registry, tid)"));
        let dump = body(&src, "\npub(crate) fn thread_dump_stack(");
        assert!(dump.contains("HeldTrace::read(registry, tid)"));
    }
}

#[cfg(test)]
mod w9_1_held_read_staleness_tests {
    use super::held_trace_is_stale;

    /// W9-1: only a WAITING / TIMED_WAITING thread outside the GC-blocked
    /// region (a lazy park or wait) whose trace was not written since before
    /// the pause is stale; a blocked thread's deposit, a republished trace,
    /// a running or BLOCKED thread, and an unknown count are not.
    #[test]
    fn w9_1_a_lazy_parker_not_republished_in_the_pause_is_stale() {
        assert!(held_trace_is_stale(3, false, Some(7), Some(7)));
        assert!(held_trace_is_stale(1, false, Some(7), Some(7)));
        assert!(
            !held_trace_is_stale(3, true, Some(7), Some(7)),
            "blocked: its deposit"
        );
        assert!(
            !held_trace_is_stale(3, false, Some(7), Some(8)),
            "republished"
        );
        assert!(!held_trace_is_stale(0, false, Some(7), Some(7)), "running");
        assert!(
            !held_trace_is_stale(2, false, Some(7), Some(7)),
            "BLOCKED on entry"
        );
        assert!(!held_trace_is_stale(3, false, None, None), "unknown thread");
    }

    /// W10-7: `CRATONVM_JMX_HELD_READ_RETRY` is default ON (three reads) and
    /// `=0` takes one.
    #[test]
    fn w10_7_the_held_read_retry_has_a_kill_switch() {
        use cratonvm_types::flags::with_thread_overrides;
        const KEY: &str = "CRATONVM_JMX_HELD_READ_RETRY";
        let read = super::held_read_attempts;
        assert_eq!(with_thread_overrides(&[(KEY, None)], read), super::HELD_READ_ATTEMPTS);
        assert_eq!(with_thread_overrides(&[(KEY, Some("1"))], read), 3);
        assert_eq!(with_thread_overrides(&[(KEY, Some("0"))], read), 1);
    }

    /// W9-1 (source pin): the snapshot retries a stale held read, and the
    /// held read takes the count inside the pause.
    #[test]
    fn w9_1_a_stale_held_read_is_taken_again() {
        let src = include_str!("vm_exec.rs").replace("\r\n", "\n");
        let start = src
            .find(concat!("    fn jmx_thread_", "snapshot(\n"))
            .expect("snapshot");
        let rest = &src[start..];
        let snapshot = &rest[..rest.find("\n    }\n").expect("its end")];
        let before = snapshot
            .find("let seq_before = registry.trace_seq(registry_tid);")
            .expect("before");
        let pause = snapshot
            .find(concat!("stw_publish_frame_traces_", "with("))
            .expect("pause");
        let retry = snapshot
            .find("if !(stale || unshaped) || attempt == attempts")
            .expect("retry");
        assert!(before < pause && pause < retry);
        // W10-7: the attempt count is the switch's, read before the loop
        // (none when a `ThreadInfo` dump's own read answers, W10-7 review).
        let count = snapshot
            .find("let attempts = if held.is_some() { 0 } else { held_read_attempts() };")
            .expect("the attempt count");
        assert!(count < before);
        let held = &src[src.find("\nimpl HeldThreadRead {").expect("held")..];
        let held = &held[..held.find("\n}\n").expect("its end")];
        assert!(held.contains("registry.trace_seq(tid)"));
        assert!(held.contains("registry.is_blocked(tid)"));
    }
}

#[cfg(test)]
mod w11_1_held_read_shape_tests {
    use super::held_read_shape_ok;

    /// W11-1: a waiting thread's held read is answered only with a native on
    /// top and, when it holds monitors, an attribution for that trace; a
    /// thread that is not waiting is answered as is.
    #[test]
    fn w11_1_a_waiting_read_needs_its_native_and_its_attribution() {
        assert!(held_read_shape_ok(true, true, 0, false));
        assert!(held_read_shape_ok(true, true, 1, true));
        assert!(
            !held_read_shape_ok(true, false, 0, false),
            "no native on top"
        );
        assert!(
            !held_read_shape_ok(true, true, 1, false),
            "monitor, no attribution"
        );
        assert!(held_read_shape_ok(false, false, 1, false), "not waiting");
    }

    /// W11 residual: a waiting read answered as running reports RUNNABLE,
    /// no waited-on lock and no parked sample (so no stand-in rows), and
    /// keeps its trace and its locked monitors.
    #[test]
    fn w11_residual_a_running_phase_read_is_answered_runnable() {
        use super::{HeldThreadRead, HeldTrace, ParkedSample};
        let mut read = HeldThreadRead {
            run_state: 5,
            trace: HeldTrace {
                trace: Vec::new(),
                parked: ParkedSample { block: 3, kind: None },
            },
            book: Some((None, None, Vec::new(), Vec::new(), 0, 0, 0, 0)),
            frame_monitors: None,
            stale: false,
        };
        read.answer_running();
        assert_eq!(read.run_state, 1);
        assert_eq!(read.trace.parked.block, 0);
        assert!(read.book.is_some_and(|book| book.1.is_none()));
    }

    /// W10-7 review (source pin): a `ThreadInfo` dump reads every target in
    /// ONE pause per attempt (the pending ones together), retries only the
    /// stale or unshaped ones, serves its reads only while current, and
    /// `end_thread_dump` drops them.
    #[test]
    fn w10_7_review_a_thread_info_dump_reads_all_targets_per_pause() {
        let src = include_str!("vm_exec.rs").replace("\r\n", "\n");
        let begin = &src[src
            .find("    fn begin_thread_info_dump(&mut self, threads: &[ObjectRef]) {")
            .expect("the batch")..];
        let begin = &begin[..begin.find("\n    }\n").expect("its end")];
        assert_eq!(begin.matches(concat!("stw_publish_frame_traces_", "with(")).count(), 1);
        assert!(begin.contains("for attempt in 1..=attempts {"));
        assert!(begin.contains("HeldThreadRead::read(shared, targets[i].0, targets[i].1, seq)"));
        assert!(begin.contains("if read.stale || !shaped {"));
        let take = &src[src
            .find("    fn take_dump_held_read(&self, tid: ThreadId)")
            .expect("the take")..];
        assert!(take[..take.find("\n    }\n").expect("its end")].contains("dump_traces_current(self)"));
        let end = &src[src.find("    fn end_thread_dump(&mut self) {").expect("the end")..];
        assert!(end[..end.find("\n    }\n").expect("its end")].contains("dump_held.lock().clear()"));
    }

    /// W11 residual (source pin): the held read's state is the block state
    /// its trace was read with, and the last unshaped read without a native
    /// is answered running only when retrying.
    #[test]
    fn w11_residual_one_block_read_and_the_running_fallback() {
        let src = include_str!("vm_exec.rs").replace("\r\n", "\n");
        let start = src
            .find(concat!("    fn jmx_thread_", "snapshot(\n"))
            .expect("snapshot");
        let rest = &src[start..];
        let snapshot = &rest[..rest.find("\n    }\n").expect("its end")];
        assert!(snapshot.contains("if attempts > 1 && lacks_native {"));
        assert!(snapshot.contains("r.answer_running();"));
        // W10-7 review: a `ThreadInfo` dump's own read comes first.
        let taken = snapshot
            .find("held = self.take_dump_held_read(registry_tid);")
            .expect("the dump's read");
        let pause = snapshot
            .find(concat!("stw_publish_frame_traces_", "with("))
            .expect("the own pause");
        assert!(taken < pause);
        assert!(src.contains(concat!(
            "run_state: registry_run_state_for_block(registry, tid, thread_obj, ",
            "block),"
        )));
    }

    /// W11-1 (source pin): the snapshot retries an unshaped read as it does
    /// a stale one, within the same attempts.
    #[test]
    fn w11_1_an_unshaped_held_read_is_taken_again() {
        let src = include_str!("vm_exec.rs").replace("\r\n", "\n");
        let start = src
            .find(concat!("    fn jmx_thread_", "snapshot(\n"))
            .expect("snapshot");
        let rest = &src[start..];
        let snapshot = &rest[..rest.find("\n    }\n").expect("its end")];
        let shape = snapshot
            .find("self.held_read_shape(r, thread_obj)")
            .expect("the shape check");
        let retry = snapshot
            .find("if !(stale || unshaped) || attempt == attempts")
            .expect("the retry");
        assert!(shape < retry);
    }
}
